/**
 * KS-719 — PUT /api/privacy/settings and PUT /api/settings/notifications
 * accepted UNAUTHENTICATED writes to a shared `'default'` bucket.
 *
 * All four handlers in this family are `authenticateToken(false)` — optional
 * auth — and each derives its storage key as `req.user?.userId || 'default'`.
 * With no bearer, the two PUTs therefore wrote to the literal key `'default'`,
 * which every other unidentified caller then read back. Not a per-user
 * compromise: there is no user to compromise. It is unauthenticated write
 * access to shared state.
 *
 * Kam ruled option 1 (2026-08-29): require auth on the PUTs; keep optional auth
 * on the GETs so an anonymous caller still gets sensible defaults. The GET-side
 * `'default'` fallback stays deliberately — anonymous READS are the supported
 * behaviour, and the must-succeed case below pins that so a later "just require
 * auth everywhere" pass cannot quietly take it away.
 *
 * These tests dispatch through the real router with the real auth middleware,
 * so they assert behaviour (401/200) rather than the presence of a middleware
 * token in source text. The `'default'` write-key assertion is the one that
 * fails loudest if the fallback is ever reintroduced on a write path.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import type { Request, Response, Router, RequestHandler } from 'express';
import { configureAuth, authenticateToken, parseTestToken } from '../middleware/auth';
import { createAdminRoutes, type AdminRouteDeps } from '../routes/admin';

// ---------------------------------------------------------------------------
// Helpers — mirrors notifications.test.ts (KS-375), the established pattern
// ---------------------------------------------------------------------------

function buildTestToken(payload: Record<string, unknown>): string {
  return `test_token_${Buffer.from(JSON.stringify(payload)).toString('base64')}`;
}

type CapturedRes = Response & { _status: number; _json: unknown };

function makeRes(onFinish: () => void): CapturedRes {
  const res: any = {
    _status: 200,
    _json: null,
    status(code: number) {
      res._status = code;
      return res;
    },
    json(body: unknown) {
      res._json = body;
      onFinish();
      return res;
    },
    setHeader() {
      return res;
    },
    send(body: unknown) {
      res._json = body;
      onFinish();
      return res;
    },
  };
  return res;
}

function dispatch(
  router: Router,
  opts: { method: string; url: string; headers?: Record<string, string>; body?: unknown },
): Promise<CapturedRes> {
  return new Promise((resolve, reject) => {
    const res = makeRes(() => resolve(res));
    const req = {
      method: opts.method,
      url: opts.url,
      headers: opts.headers || {},
      body: opts.body,
      query: {},
      get(name: string) {
        return (this as any).headers[name?.toLowerCase()];
      },
    } as unknown as Request;
    router(req, res as any, (err: unknown) => (err ? reject(err) : resolve(res)));
  });
}

/**
 * Records every key written so a test can assert WHICH bucket a write landed
 * in — the `'default'` shared bucket being the whole point of KS-719.
 */
function makeRecordingRedis() {
  const privacy = new Map<string, unknown>();
  const notif = new Map<string, unknown>();
  const writes: Array<{ store: 'privacy' | 'notif'; key: string }> = [];
  return {
    writes,
    service: {
      getPrivacySettings: async (key: string) => (privacy.has(key) ? privacy.get(key) : null),
      setPrivacySettings: async (key: string, value: unknown) => {
        writes.push({ store: 'privacy', key });
        privacy.set(key, value);
      },
      getNotificationSettings: async (key: string) => (notif.has(key) ? notif.get(key) : null),
      setNotificationSettings: async (key: string, value: unknown) => {
        writes.push({ store: 'notif', key });
        notif.set(key, value);
      },
    },
  };
}

function buildRouter(redisService: object): Router {
  const passThroughBodyParser: RequestHandler = (_req, _res, next) => next();
  return createAdminRoutes({
    authenticateToken,
    parseTestToken,
    mockBodyParser: passThroughBodyParser,
    query: async () => ({ rows: [], rowCount: 0 }),
    isDbAvailable: () => false,
    redisService,
    services: {},
    log: () => undefined,
  } as unknown as AdminRouteDeps);
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('KS-719 — the settings PUTs must require authentication', () => {
  let redis: ReturnType<typeof makeRecordingRedis>;
  let router: Router;

  beforeEach(() => {
    vi.stubEnv('NODE_ENV', 'test');
    configureAuth({ enableTestTokens: true, defaultTenantId: 'default' });
    redis = makeRecordingRedis();
    router = buildRouter(redis.service);
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  const authed = (sub: string) => ({
    authorization: `Bearer ${buildTestToken({ sub, role: 'user', email: `${sub}@test.io` })}`,
  });

  describe('anonymous writes are refused', () => {
    it('PUT /api/privacy/settings with no bearer returns 401, not 200', async () => {
      const res = await dispatch(router, {
        method: 'PUT',
        url: '/api/privacy/settings',
        body: { autoRejectUnknown: true },
      });
      expect(res._status).toBe(401);
      expect((res._json as any).error.code).toBe('UNAUTHORIZED');
    });

    it('PUT /api/settings/notifications with no bearer returns 401, not 200', async () => {
      const res = await dispatch(router, {
        method: 'PUT',
        url: '/api/settings/notifications',
        body: { certificationNotifications: false },
      });
      expect(res._status).toBe(401);
      expect((res._json as any).error.code).toBe('UNAUTHORIZED');
    });

    it('an anonymous PUT performs NO write at all — nothing reaches the shared bucket', async () => {
      // The status code alone would still pass if the handler wrote and then
      // 401'd. This asserts the defect itself: no key was touched.
      await dispatch(router, { method: 'PUT', url: '/api/privacy/settings', body: { x: 1 } });
      await dispatch(router, { method: 'PUT', url: '/api/settings/notifications', body: { x: 1 } });
      expect(redis.writes).toEqual([]);
    });
  });

  describe('authenticated writes still work, and land in the caller’s own bucket', () => {
    it('PUT /api/privacy/settings with a bearer returns 200 and writes to the user’s key', async () => {
      const res = await dispatch(router, {
        method: 'PUT',
        url: '/api/privacy/settings',
        headers: authed('user-alpha'),
        body: { autoRejectUnknown: true },
      });
      expect(res._status).toBe(200);
      expect((res._json as any).success).toBe(true);
      expect(redis.writes).toContainEqual({ store: 'privacy', key: 'priv-settings-user-alpha' });
      // The shared bucket must never be the destination for an authed write.
      expect(redis.writes.map((w) => w.key)).not.toContain('priv-settings-default');
    });

    it('PUT /api/settings/notifications with a bearer returns 200 and writes to the user’s key', async () => {
      const res = await dispatch(router, {
        method: 'PUT',
        url: '/api/settings/notifications',
        headers: authed('user-beta'),
        body: { certificationNotifications: false },
      });
      expect(res._status).toBe(200);
      expect(redis.writes).toContainEqual({ store: 'notif', key: 'user-beta' });
      expect(redis.writes.map((w) => w.key)).not.toContain('default');
    });
  });

  describe('the must-succeed case — anonymous READS keep working', () => {
    it('GET /api/privacy/settings with no bearer still returns 200 with the documented defaults', async () => {
      const res = await dispatch(router, { method: 'GET', url: '/api/privacy/settings' });
      expect(res._status).toBe(200);
      expect((res._json as any).settings).toEqual({
        autoRejectUnknown: false,
        preferRangeProofs: true,
        preferCommitments: true,
        logAllDisclosures: true,
        notifyOnDisclosure: true,
      });
    });

    it('GET /api/settings/notifications with no bearer still returns 200 with the documented defaults', async () => {
      const res = await dispatch(router, { method: 'GET', url: '/api/settings/notifications' });
      expect(res._status).toBe(200);
      expect(res._json).toMatchObject({
        success: true,
        certificationNotifications: true,
        verificationNotifications: true,
      });
    });
  });

  describe('controls', () => {
    it('control: the harness CAN observe a write — otherwise the no-write assertion is vacuous', async () => {
      // If makeRecordingRedis or the body parser were wired wrong, `writes`
      // would be empty for every request and the anonymous-write test above
      // would pass no matter what the handler did.
      await dispatch(router, {
        method: 'PUT',
        url: '/api/privacy/settings',
        headers: authed('control-user'),
